value.fa:
عدد دما = 25;
اگر دما > 30: {
    چاپ("هوا گرم است");
} وگرنه اگر دما > 20: {
    چاپ("هوا مطبوع است");
} وگرنه: {
    چاپ("هوا سرد است");
}

// حالت تک‌دستوری
عدد a = 10;
اگر a == 10: چاپ("a دقیقاً ۱۰ است");

value.en:
int temp = 25;
if temp > 30: {
    print("It is hot");
} else if temp > 20: {
    print("It is mild");
} else: {
    print("It is cold");
}

// Single-statement mode
int a = 10;
if a == 10: print("a is exactly 10");

value.ja:
整数 temp = 25;
もし temp > 30: {
    表示("暑いです");
} それ以外 もし temp > 20: {
    表示("快適です");
} それ以外: {
    表示("寒いです");
}

// 単一ステートメントモード
整数 a = 10;
もし a == 10: 表示("aは正確に10です");

value.ru:
цел temp = 25;
если temp > 30: {
    печать("Жарко");
} иначе если temp > 20: {
    печать("Приятно");
} иначе: {
    печать("Холодно");
}

// Режим одиночного оператора
цел a = 10;
если a == 10: печать("a ровно 10");
